4px;max-width:100%;height:auto;border:0\"></a></td></tr><tr><td class=\"email-content\" dir=\"ltr\" style=\"padding:34px 36px;text-align:left;font-family:Cairo,Arial,Helvetica,sans-serif\"><h1 class=\"email-heading\" style=\"margin:0 0 20px;font-size:28px;line-height:1.5;font-weight:800;color:#510504;overflow-wrap:anywhere\">Your invitation to Etsawaa</h1><p style=\"margin:0 0 16px;font-size:16px;line-height:1.9;overflow-wrap:anywhere\">Use your secure link to activate your account and set your password.</p><table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin:28px 0\"><tr><td align=\"center\" bgcolor=\"#be0404\" style=\"border-radius:10px;mso-padding-alt:14px 28px\"><a href=\"{{confirmation_url}}\" style=\"display:inline-block;padding:14px 28px;background:#be0404;border:1px solid #be0404;border-radius:10px;color:#ffffff;text-decoration:none;font-family:Cairo,Arial,Helvetica,sans-serif;font-size:15px;line-height:24px;font-weight:700;text-align:center\">Activate your account</a></td></tr></table><p style=\"margin:24px 0 0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.9;color:#596273\">Valid for {{expires_minutes}} minutes from the time of your request. Never share your code or link.<br>If you didn’t request this, ignore this email.</p></td></tr><tr><td align=\"center\" style=\"padding:22px 24px;border-top:1px solid #e5e7eb;background:#fafafa;font-family:Cairo,Arial,Helvetica,sans-serif;font-size:13px;line-height:1.9;color:#596273\">Need a hand? The Etsawaa team is here to help.<br><a href=\"https://etsawaa.com/en/contact\" style=\"color:#be0404;text-decoration:underline\">Contact us</a><br><a href=\"https://etsawaa.com/en\" style=\"color:#596273;text-decoration:none\">etsawaa.com</a></td></tr></table><p style=\"margin:18px 0 0;font-family:Cairo,Arial,Helvetica,sans-serif;font-size:12px;line-height:1.8;color:#596273\">Etsawaa · Find your next favourite</p></td></tr></table></body></html>"}]$email_catalog$::jsonb)
)
insert into public.email_templates(key,name_ar,name_en,audience,variables,subject_ar,subject_en,html_ar,html_en,content_ar,content_en)
select d->>'key',d->>'name_ar',d->>'name_en',d->>'audience',d->'variables',
 d->'content'->'ar'->>'subject',d->'content'->'en'->>'subject',d->>'html_ar',d->>'html_en',d->'content'->'ar',d->'content'->'en'
from definitions
on conflict(key) do update set name_ar=excluded.name_ar,name_en=excluded.name_en,audience=excluded.audience,
 variables=excluded.variables,subject_ar=excluded.subject_ar,subject_en=excluded.subject_en,
 html_ar=excluded.html_ar,html_en=excluded.html_en,content_ar=excluded.content_ar,content_en=excluded.content_en,
 version=email_templates.version+1,revision=email_templates.revision+1,updated_at=now()
where email_templates.content_ar is null and email_templates.content_en is null;
insert into public.email_template_versions(template_key,version,snapshot)
select key,version,to_jsonb(t) from public.email_templates t where content_ar is not null on conflict do nothing;


do $$
declare t public.email_templates; c jsonb; result jsonb; r integer; v integer; admin_id uuid;
begin
 if (select count(*) from public.email_templates where content_ar is not null)<>57 then raise exception 'catalog count'; end if;
 if exists(select 1 from public.email_templates where not public.email_content_valid(jsonb_build_object('ar',content_ar,'en',content_en),variables)) then raise exception 'invalid catalog'; end if;
 select id into admin_id from public.profiles where role='admin' limit 1;
 if admin_id is null then raise exception 'admin missing'; end if;
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',admin_id,'role','authenticated')::text,true);
 if not public.can_edit_email_templates() then raise exception 'admin permission'; end if;
 select * into t from public.email_templates where key='welcome';
 c:=jsonb_build_object('ar',t.content_ar,'en',t.content_en);
 c:=jsonb_set(c,'{ar,heading}',to_jsonb('QA draft only'::text));
 result:=public.fn_admin_edit_email_template('welcome',t.revision,'draft',c);
 if not (result->>'ok')::boolean then raise exception 'draft save: %',result; end if;
 if (select content_ar from public.email_templates where key='welcome')<>t.content_ar then raise exception 'draft leaked'; end if;
 result:=public.fn_admin_edit_email_template('welcome',t.revision,'publish',c);
 if result->>'reason'<>'conflict' then raise exception 'stale update accepted'; end if;
 select revision into r from public.email_templates where key='welcome';
 result:=public.fn_admin_edit_email_template('welcome',r,'publish',c);
 if not (result->>'ok')::boolean then raise exception 'publish failed'; end if;
 select revision,version into r,v from public.email_templates where key='welcome';
 if v<>t.version+1 or (select draft_content from public.email_templates where key='welcome') is not null then raise exception 'publish state'; end if;
 result:=public.fn_admin_edit_email_template('welcome',r,'restore',null,t.version);
 if not (result->>'ok')::boolean or (select content_ar from public.email_templates where key='welcome')<>t.content_ar then raise exception 'restore'; end if;
 if public.fn_admin_set_email_template_active('auth:signup',false)->>'reason'<>'security_required' then raise exception 'auth pause'; end if;
 select * into t from public.email_templates where key='auth:signup';
 c:=jsonb_build_object('ar',t.content_ar,'en',t.content_en);
 c:=jsonb_set(jsonb_set(c,'{ar,code}','""'),'{en,code}','""');
 if public.fn_admin_edit_email_template('auth:signup',t.revision,'publish',c)->>'reason'<>'invalid_content' then raise exception 'missing code accepted'; end if;
 if not public.fn_set_preferred_locale('en') or (select locale from public.profiles where id=admin_id)<>'en' then raise exception 'locale not persisted'; end if;
 if public.fn_set_preferred_locale('fr') then raise exception 'invalid locale accepted'; end if;
 perform public.fn_enqueue_auth_email(repeat('a',64),'encrypted-test-only',now()+interval '5 minutes');
 perform public.fn_enqueue_auth_email(repeat('a',64),'duplicate-must-not-replace',now()+interval '5 minutes');
 if (select payload from public.auth_email_deliveries where id=repeat('a',64))<>'encrypted-test-only' then raise exception 'enqueue duplicate'; end if;
 if has_function_privilege('authenticated','public.fn_enqueue_auth_email(text,text,timestamptz)','execute') then raise exception 'enqueue exposed'; end if;
 if public.fn_claim_auth_email('qa-hash')<>'claimed' or public.fn_claim_auth_email('qa-hash')<>'busy' then raise exception 'claim concurrency'; end if;
 update public.auth_email_deliveries set status='sent' where id='qa-hash';
 if public.fn_claim_auth_email('qa-hash')<>'sent' then raise exception 'claim replay'; end if;
 if has_function_privilege('authenticated','public.fn_claim_auth_email(text)','execute') then raise exception 'hook claim exposed'; end if;
 if not has_function_privilege('service_role','public.fn_claim_auth_email(text)','execute') then raise exception 'hook service permission'; end if;
 perform set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
 perform set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
 if public.fn_admin_email_templates()->>'reason'<>'forbidden' then raise exception 'unauthorized read'; end if;
 if public.fn_admin_edit_email_template('welcome',1,'draft',c)->>'reason'<>'forbidden' then raise exception 'unauthorized write'; end if;
end $$;
select 'PASS: catalog, draft isolation, optimistic lock, publish, history/restore, Auth protection, locale, permissions and replay prevention' as verification;
ROLLBACK;
